import { resolve } from 'node:path'

// Resolved from this module, which sits one level below the package root both as `src/paths.ts`
// and bundled into `dist/index.js`, so the path holds in dev, tests and the Docker image.

/** SQL migrations generated by `pnpm --filter server db:generate` (see drizzle.config.ts). */
export const MIGRATIONS_DIR = resolve(import.meta.dirname, '../drizzle')

/** Built frontend, served by the backend in production. */
export const STATIC_DIR = resolve(import.meta.dirname, '../../web/dist')
